// Generated by scripts/sync-valuation.py from shared/valuation/horizon.js as rp-valuation-horizon.js; edit the shared source.
// Turn/receipt horizon and discounting. Pure ES module: no game globals.
//
// Canonical count used by the user's example:
//   currentTurn=100, endTurn=120, firstReceiptTurn=101 -> 20 receipts
// Receipts are end-of-turn events after the current turn, inclusive of endTurn.
// A construction delay of d turns uses firstReceiptTurn = current + d + 1, so
// delay=0 still includes turn 101 and delay=1 starts at 102 (19 receipts).

import {isFiniteNumber} from './rp-valuation-weights.js';

export const TURN_RULE = 'receipts-after-current-through-end-inclusive';

function integer(value) {
  return typeof value === 'number' && Number.isInteger(value);
}

function rate(value) {
  return isFiniteNumber(value) && value >= 0 ? value : null;
}

export function firstReceiptTurnAfterDelay(currentTurn, delayTurns = 0) {
  if (!integer(currentTurn) || !integer(delayTurns) || delayTurns < 0) return null;
  return currentTurn + delayTurns + 1;
}

export function normalizeHorizon(input = {}) {
  const currentTurn = input.currentTurn;
  const endTurn = input.endTurn;
  const firstReceiptTurn = input.firstReceiptTurn === undefined
    ? firstReceiptTurnAfterDelay(currentTurn, 0)
    : input.firstReceiptTurn;
  const discountRate = input.discountRate === undefined ? 0 : input.discountRate;
  if (!integer(currentTurn)) return Object.freeze({status: 'invalid', reason: 'currentTurn-integer-required', currentTurn: null, endTurn, firstReceiptTurn, discountRate: null, count: 0, startTurn: null});
  if (!integer(endTurn)) return Object.freeze({status: 'invalid', reason: 'endTurn-integer-required', currentTurn, endTurn: null, firstReceiptTurn, discountRate: null, count: 0, startTurn: null});
  if (!integer(firstReceiptTurn)) return Object.freeze({status: 'invalid', reason: 'firstReceiptTurn-integer-required', currentTurn, endTurn, firstReceiptTurn: null, discountRate: null, count: 0, startTurn: null});
  if (rate(discountRate) === null) return Object.freeze({status: 'invalid', reason: 'discountRate-non-negative-finite-required', currentTurn, endTurn, firstReceiptTurn, discountRate: null, count: 0, startTurn: null});
  if (currentTurn >= endTurn) {
    return Object.freeze({status: 'ended', reason: 'at-or-after-end-turn', currentTurn, endTurn, firstReceiptTurn, discountRate, count: 0, startTurn: null, lastTurn: null, rule: TURN_RULE});
  }
  const startTurn = Math.max(firstReceiptTurn, currentTurn + 1);
  if (startTurn > endTurn) {
    return Object.freeze({status: 'ended', reason: 'first-receipt-after-end-turn', currentTurn, endTurn, firstReceiptTurn, discountRate, count: 0, startTurn: null, lastTurn: null, rule: TURN_RULE});
  }
  const count = endTurn - startTurn + 1;
  return Object.freeze({status: 'estimated', currentTurn, endTurn, firstReceiptTurn, discountRate, count, startTurn, lastTurn: endTurn, rule: TURN_RULE});
}

export function receiptCount(input = {}) {
  return normalizeHorizon(input).count;
}

// Sum of a constant per-turn flow over [startTurn, endTurn] in the horizon.
// Discount exponent is measured from currentTurn; the first receipt is not
// discounted to zero automatically, which keeps r=0 and r>0 comparable.
export function discountedRangeSum(perTurnValue, input = {}) {
  if (!isFiniteNumber(perTurnValue)) return null;
  const horizon = normalizeHorizon(input);
  if (horizon.status === 'invalid') return null;
  if (horizon.count === 0) return 0;
  const r = horizon.discountRate;
  if (r === 0) {
    const value = perTurnValue * horizon.count;
    return isFiniteNumber(value) ? value : null;
  }
  const q = 1 / (1 + r);
  const firstExponent = horizon.startTurn - horizon.currentTurn;
  const growth = q ** horizon.count;
  const geometric = Math.abs(q - 1) < 1e-12
    ? horizon.count
    : (q ** firstExponent) * (1 - growth) / (1 - q);
  const value = perTurnValue * geometric;
  return isFiniteNumber(value) ? value : null;
}

// Coarse time value assembled from one immediate net amount and a recurring
// per-turn amount. Immediate cost/benefit is never discounted or multiplied by
// remaining receipts. Invalid inputs produce null, never NaN or a fake zero.
export function evaluateHorizonValue({
  perTurnValue = 0,
  immediateCost = 0,
  immediateBenefit = 0,
  currentTurn,
  endTurn,
  firstReceiptTurn,
  discountRate = 0
} = {}) {
  if (!isFiniteNumber(perTurnValue) || !isFiniteNumber(immediateCost) || !isFiniteNumber(immediateBenefit)) {
    return Object.freeze({status: 'invalid', reason: 'non-finite-value', total: null, recurring: null, immediateNet: null, horizon: null});
  }
  if (immediateCost < 0) return Object.freeze({status: 'invalid', reason: 'immediateCost-non-negative', total: null, recurring: null, immediateNet: null, horizon: null});
  const horizon = normalizeHorizon({currentTurn, endTurn, firstReceiptTurn, discountRate});
  if (horizon.status === 'invalid') return Object.freeze({status: 'invalid', reason: horizon.reason, total: null, recurring: null, immediateNet: null, horizon});
  const recurring = horizon.count === 0 ? 0 : discountedRangeSum(perTurnValue, horizon);
  if (recurring === null) return Object.freeze({status: 'invalid', reason: 'discount-evaluation-failed', total: null, recurring: null, immediateNet: null, horizon});
  const immediateNet = immediateBenefit - immediateCost;
  const total = immediateNet + recurring;
  if (!isFiniteNumber(immediateNet) || !isFiniteNumber(total)) {
    return Object.freeze({status: 'invalid', reason: 'value-overflow', total: null, recurring: null, immediateNet: null, horizon});
  }
  return Object.freeze({
    status: horizon.count ? 'estimated' : 'ended',
    total,
    immediateCost,
    immediateBenefit,
    immediateNet,
    recurring,
    recurringUndiscounted: perTurnValue * horizon.count,
    perTurnValue,
    horizon,
    rule: TURN_RULE
  });
}

export function affordability({goldStock, quotedCost} = {}) {
  if (!isFiniteNumber(goldStock) || !isFiniteNumber(quotedCost) || goldStock < 0 || quotedCost < 0) {
    return Object.freeze({status: 'invalid', reason: 'non-negative-finite-gold-required', affordable: null, shortfall: null, remaining: null, goldStock, quotedCost});
  }
  const shortfall = Math.max(0, quotedCost - goldStock);
  return Object.freeze({
    status: 'estimated',
    affordable: shortfall === 0,
    shortfall,
    remaining: goldStock - quotedCost,
    goldStock,
    quotedCost,
    note: 'goldStock pays once; per-turn gold income is a separate flow'
  });
}
